mapper.select:
		select s.selling_no, s.store_no,s.selling_date, 
			s.selling_total, sd.menu_no, sd.selling_amount, st.store_nm, m.menu_nm,m.menu_price, c.ctgry_nm  
		from selling s, selling_detail sd, store st, menu m, ctgry c
		where s.selling_no = sd.selling_no
		and st.store_no=s.store_no
		and m.menu_no=sd.menu_no
		and c.ctgry_no=m.ctgry_no
	    and  extract(month from s.selling_date)= #{month}
   		and  extract(year from s.selling_date)= #{year}

			and st.store_no=#{storeNo}

select rank, month, year, item_nm,total
from(
select row_number() over(order by total desc) as rank, item_nm,
		    year, month,total
		from(select i.item_nm,i.item_no,
		    extract(year from s.store_order_date) as year,
		    extract(month from s.store_order_date) as month,
		    sum(store_order_amount) as total
		from store_order_detail sd, store_order s, item i
		where sd.store_order_no=s.store_order_no
		and i.item_no = sd.item_no
		and s.store_order_status=1
		and extract(year from s.store_order_date)=#{year}
		and extract(month from s.store_order_date)=#{month}
        group by extract(year from s.store_order_date),extract(month from s.store_order_date),i.item_nm,i.item_no)
)where rank between 1 and 5

select row_number() over(order by total desc) as rank, menu_nm, year, month, menu_no, total
from(
select m.menu_no,m.menu_nm,extract(year from selling_date) year,extract(month from selling_date) month,
        sum(selling_amount) total
from selling s, selling_detail sd, menu m
where m.menu_no=sd.menu_no
and s.selling_no=sd.selling_no
and extract(year from selling_date)=#{year}
and extract(month from selling_date)=#{month}
group by  m.menu_no,m.menu_nm,extract(year from selling_date) ,extract(month from selling_date))

select rank, month, year, menu_nm,total
from(	
select row_number() over(order by total desc) as rank, menu_nm, year, month, menu_no, total
from(
select m.menu_no,m.menu_nm,extract(year from selling_date) year,extract(month from selling_date) month,
    sum(selling_amount) total
from selling s, selling_detail sd, menu m
where m.menu_no=sd.menu_no
and s.selling_no=sd.selling_no
and extract(year from selling_date)=#{year}
and extract(month from selling_date)=#{month}
group by  m.menu_no,m.menu_nm,extract(year from selling_date) ,extract(month from selling_date))
)where rank between 1 and 5

mapper.update:
update selling
set selling_total=#{sellingTotal}
where selling_no=#{sellingNo}
